package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.time.Instant;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;

/** Native hardware observations with explicit identity, source authority and manual-conflict handling. */
final class DiscoveryReconciliation {
 static final Set<String> FIELDS=Set.of("short_description","name","description","location");
 private DiscoveryReconciliation() {}
 static String serial(Object value){String s=WorkJobs.text(value,160).strip().toUpperCase(Locale.ROOT);require(s.matches("[A-Z0-9][A-Z0-9._:/-]{0,159}"),"Use a bounded canonical hardware serial number");return s;}
 static Map<String,Object> source(Store.Db db,String id)throws SQLException{var row=db.one("SELECT * FROM os_discovery_source WHERE source_id=?",id);if(row==null)throw new Failure(404,"Discovery source not found");row.put("attributes",JSON.readValue(row.get("attributes").toString(),List.class));return row;}
 static Map<String,Object> adminPage(Store.Db db,String id)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);var selected=id.isEmpty()?map("source_id","","name","","alias","","path","/observations","priority",100,"attributes",List.of("short_description","name","description","location"),"allow_create",0,"adopt_existing",0,"active",0,"revision",0):source(db,id);var connector=db.one("SELECT * FROM os_connector WHERE alias=?",selected.get("alias"));return map("sources",db.all("SELECT source_id,name,active,priority FROM os_discovery_source ORDER BY name"),"source",selected,"connectors",db.all("SELECT alias,origin,revision FROM os_connector ORDER BY alias LIMIT 100"),"connector_review",connector==null?"":Connectors.review(connector),"origin",connector==null?"Unavailable connector":connector.get("origin"),"reports",id.isEmpty()?List.of():db.all("SELECT report_id,external_id,observed_at,created FROM os_discovery_report WHERE source_id=? ORDER BY created DESC,report_id LIMIT 100",id));
 }
 static Map<String,Object> configure(Store.Db db,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("revision","name","alias","path","priority","attributes","allow_create","adopt_existing","active")),"Provide the reviewed source configuration only");var old=id.isEmpty()?map("revision",0):source(db,id);ProblemInvestigations.revision(body.get("revision"),old.get("revision"));String name=WorkJobs.text(body.get("name"),160),alias=WorkJobs.text(body.get("alias"),80),path=Connectors.path(body.get("path"));require(body.get("priority") instanceof Integer n && n>=1 && n<=1000,"Use authority rank 1–1000");for(String field:List.of("allow_create","adopt_existing","active"))require(body.get(field) instanceof Boolean,"Choose each source permission explicitly");require(body.get("attributes") instanceof List<?>,"Choose allowed discovery fields");var attributes=(List<?>)body.get("attributes");require(!attributes.isEmpty() && attributes.size()<=4 && new HashSet<>(attributes).size()==attributes.size() && FIELDS.containsAll(attributes),"Choose unique native discovery fields");if((Boolean)body.get("active") && db.one("SELECT alias FROM os_connector WHERE alias=?",alias)==null)throw new Failure(409,"Configure the connector before activating this source");if(!id.isEmpty() && db.count("SELECT COUNT(*) FROM os_discovery_report WHERE source_id=?",id)>0 && (!alias.equals(old.get("alias")) || !path.equals(old.get("path"))))throw new Failure(409,"A source with retained reports cannot change connector alias or path");if(id.isEmpty()){require(db.count("SELECT COUNT(*) FROM os_discovery_source")<100,"At most 100 discovery sources are supported");id=Values.id();}db.update("INSERT INTO os_discovery_source(source_id,name,alias,path,priority,attributes,allow_create,adopt_existing,active,revision) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET name=excluded.name,alias=excluded.alias,path=excluded.path,priority=excluded.priority,attributes=excluded.attributes,allow_create=excluded.allow_create,adopt_existing=excluded.adopt_existing,active=excluded.active,revision=excluded.revision",id,name,alias,path,body.get("priority"),JSON.writeValueAsString(attributes),(Boolean)body.get("allow_create")?1:0,(Boolean)body.get("adopt_existing")?1:0,(Boolean)body.get("active")?1:0,((Number)old.get("revision")).intValue()+1);SecurityEvents.record(db,db.viewerId,db.viewerId,"discovery.source_configured",map("source_id",id));return adminPage(db,id);
 }
 static Map<String,Object> receipt(Store.Db db,String id)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);var row=db.one("SELECT * FROM os_discovery_report WHERE report_id=?",id);if(row==null)throw new Failure(404,"Discovery report not found");var entries=new ArrayList<Map<String,Object>>();for(var outcome:objects(object(row.get("detail")).get("outcomes"))){var item=Service.readRecord(db,"cmdb_ci",outcome.get("record_id").toString());var entry=new LinkedHashMap<>(outcome);entry.put("record",FieldAccess.serialize(db,item));entries.add(entry);}row.put("outcomes",entries);row.remove("detail");return row;
 }
 static void writeField(Store.Db db,String field)throws SQLException {var schema=Service.schema(db,"cmdb_ci");FieldAccess.writing(db,schema,map(field,""));var rule=object(TypedFields.rules(schema).getOrDefault(field,map()));if(rule.containsKey("write_roles") && !((List<?>)rule.get("write_roles")).contains(db.viewerRole))throw new Failure(403,"Discovery field write permission required");}
 static Map<String,Object> ciPage(Store.Db db,String id)throws Exception {
  var item=Service.readRecord(db,"cmdb_ci",id);var fields=new ArrayList<Map<String,Object>>();var schema=Service.schema(db,"cmdb_ci");for(var row:db.all("SELECT f.*,s.name AS source_name FROM os_discovery_field f JOIN os_discovery_source s ON s.source_id=f.source_id WHERE f.record_id=? ORDER BY f.field",id)){String field=row.get("field").toString();if(!FieldAccess.allowed(db,schema,field))continue;row.put("manual_conflict",!row.remove("value_hash").equals(DigestUtils.sha256Hex(object(item.get("data")).getOrDefault(field,"").toString())));fields.add(row);}var identity=db.one("SELECT serial_number FROM os_discovery_identity WHERE record_id=?",id);return map("record",FieldAccess.serialize(db,item),"serial",identity==null || !FieldAccess.allowed(db,schema,"serial_number")?"":identity.get("serial_number"),"fields",fields,"can_release","admin".equals(db.viewerRole));
 }
 static Map<String,Object> release(Store.Db db,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var item=Service.record(db,"cmdb_ci",id);RecordPolicy.require(Service.schema(db,"cmdb_ci"),"update",db.viewerRole);var body=object(input);require(body.keySet().equals(Set.of("field","record_revision","report_id","reason")),"Provide field, current record revision, observed report and reason");String field=WorkJobs.text(body.get("field"),80),reason=WorkJobs.text(body.get("reason"),2000);require(FIELDS.contains(field),"Choose a native discovery field");writeField(db,field);ProblemInvestigations.revision(body.get("record_revision"),item.get("revision"));var prior=db.one("SELECT source_id,report_id,released FROM os_discovery_field WHERE record_id=? AND field=?",id,field);if(prior==null)throw new Failure(404,"Discovery field ownership not found");if(!prior.get("report_id").equals(body.get("report_id")))throw new Failure(409,"Field evidence changed; review the current report");if(((Number)prior.get("released")).intValue()==1)throw new Failure(409,"Field already awaits a newer observation");db.update("UPDATE os_discovery_field SET released=1,value_hash=? WHERE record_id=? AND field=?",DigestUtils.sha256Hex(object(item.get("data")).getOrDefault(field,"").toString()),id,field);Service.audit(db,item,Service.account(db,db.viewerId).get("name").toString(),"discovery.field_released",map("field",field,"source_id",prior.get("source_id"),"report_id",prior.get("report_id"),"reason",reason));return ciPage(db,id);
 }
 static Map<String,Object> ingest(Store store,Store.Db db,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var source=source(db,id);if(((Number)source.get("active")).intValue()!=1)throw new Failure(409,"Discovery source is inactive");var body=object(input);require(body.keySet().equals(Set.of("revision","connector_review")),"Provide current source revision and connector review");ProblemInvestigations.revision(body.get("revision"),source.get("revision"));var connector=ConnectorConsole.page(db,source.get("alias").toString());var fetched=Connectors.fetch(store,db,map("alias",source.get("alias"),"path",source.get("path"),"review",body.get("connector_review")));byte[] bytes=(byte[])fetched.get("content");Map<String,Object> report;try{report=object(JSON.readValue(bytes,Object.class));}catch(tools.jackson.core.JacksonException invalid){throw new Failure(400,"Discovery response must be a native JSON report");}require(report.keySet().equals(Set.of("report_id","observed_at","items")),"Provide native report identity, observation time and items");String external=WorkJobs.text(report.get("report_id"),160),observed=VulnerabilityResponse.observed(report.get("observed_at")),digest=DigestUtils.sha256Hex(bytes);require(report.get("items") instanceof List<?> rows && !rows.isEmpty() && rows.size()<=50,"A discovery report contains 1–50 observations");String provenance=DigestUtils.sha256Hex(JSON.writeValueAsString(map("alias",source.get("alias"),"path",source.get("path"),"origin",connector.get("origin"))));var previous=db.one("SELECT report_id,sha256,provenance_hash FROM os_discovery_report WHERE source_id=? AND external_id=?",id,external);if(previous!=null){if(!digest.equals(previous.get("sha256")) || !provenance.equals(previous.get("provenance_hash")))throw new Failure(409,"Report identity already represents different evidence or source");return receipt(db,previous.get("report_id").toString());}require(db.count("SELECT COUNT(*) FROM os_discovery_report WHERE source_id=?",id)<1000,"Discovery source report capacity reached");RecordPolicy.read(db,Service.schema(db,"cmdb_ci"));var identities=new HashSet<String>();var entries=new ArrayList<Map<String,Object>>();for(Object raw:(List<?>)report.get("items")){var entry=object(raw);require(entry.keySet().equals(Set.of("serial_number","attributes")),"Provide only hardware serial and attributes");String serial=serial(entry.get("serial_number"));require(identities.add(serial),"Each serial appears once in a report");var attributes=object(entry.get("attributes"));require(!attributes.isEmpty() && new HashSet<>((List<?>)source.get("attributes")).containsAll(attributes.keySet()),"Observation fields must be authorized by this source");for(var field:attributes.entrySet()){require(field.getValue() instanceof String value && value.length()<=4000 && value.indexOf('\0')<0,"Discovery attributes must be bounded text without NUL");if(field.getKey().equals("short_description"))require(!field.getValue().toString().isBlank() && field.getValue().toString().length()<=160,"Provide a summary of 1–160 characters");}entries.add(map("serial",serial,"attributes",attributes));}
  String reportId=Values.id(),actor=Service.account(db,db.viewerId).get("name").toString();var outcomes=new ArrayList<Map<String,Object>>();for(var entry:entries){String serial=entry.get("serial").toString();var attributes=object(entry.get("attributes"));var identity=db.one("SELECT record_id FROM os_discovery_identity WHERE serial_number=?",serial);Map<String,Object> item;boolean created=false,adopted=false;if(identity==null){String column=Service.columns(db,Service.schema(db,"cmdb_ci")).get("serial_number");require(column!=null,"Serial-number identity must be readable");var matches=db.all("SELECT sys_id FROM os_record WHERE \"table\"='cmdb_ci' AND UPPER(TRIM("+column+"))=?",serial);if(matches.size()>1)throw new Failure(409,"Serial number matches multiple existing CIs; resolve identity first");if(matches.isEmpty()){require(((Number)source.get("allow_create")).intValue()==1,"This source cannot create a new CI");require(attributes.containsKey("short_description"),"New CIs require a source summary");var initial=new LinkedHashMap<>(attributes);initial.put("serial_number",serial);for(String field:initial.keySet())writeField(db,field);item=Service.create(db,"cmdb_ci",initial,actor);created=true;}else{require(((Number)source.get("adopt_existing")).intValue()==1,"Explicit permission is required to adopt an existing CI");item=Service.record(db,"cmdb_ci",matches.getFirst().get("sys_id").toString());if(db.one("SELECT record_id FROM os_discovery_identity WHERE record_id=?",item.get("sys_id"))!=null)throw new Failure(409,"CI is already bound to a different serial identity");adopted=true;}db.update("INSERT INTO os_discovery_identity(record_id,serial_number) VALUES(?,?)",item.get("sys_id"),serial);}else item=Service.record(db,"cmdb_ci",identity.get("record_id").toString());String target=item.get("sys_id").toString();RecordPolicy.require(Service.schema(db,"cmdb_ci"),"update",db.viewerRole);var data=object(item.get("data"));var patch=map();var decisions=map();var accepted=new ArrayList<String>();for(var field:attributes.entrySet()){String key=field.getKey(),value=field.getValue().toString();var prior=db.one("SELECT * FROM os_discovery_field WHERE record_id=? AND field=?",target,key);String decision="accepted";if(prior!=null){if(!prior.get("value_hash").equals(DigestUtils.sha256Hex(data.getOrDefault(key,"").toString())))decision="manual_conflict";else if(!Instant.parse(observed).isAfter(Instant.parse(prior.get("observed_at").toString())))decision="stale_observation";else if(((Number)prior.get("released")).intValue()==0 && ((Number)source.get("priority")).intValue()>((Number)prior.get("priority")).intValue())decision="lower_authority";}if(decision.equals("accepted")){writeField(db,key);accepted.add(key);if(!value.equals(data.getOrDefault(key,"")))patch.put(key,value);}decisions.put(key,decision);}if(!patch.isEmpty())Service.update(db,"cmdb_ci",item,patch,actor,db.viewerRole,item.get("revision").toString());for(String field:accepted)db.update("INSERT INTO os_discovery_field(record_id,field,source_id,priority,observed_at,value_hash,report_id) VALUES(?,?,?,?,?,?,?) ON CONFLICT(record_id,field) DO UPDATE SET source_id=excluded.source_id,priority=excluded.priority,observed_at=excluded.observed_at,value_hash=excluded.value_hash,report_id=excluded.report_id,released=0",target,field,id,source.get("priority"),observed,DigestUtils.sha256Hex(attributes.get(field).toString()),reportId);String status=created?"created":adopted?"adopted":patch.isEmpty()?"unchanged":"updated";outcomes.add(map("record_id",target,"status",status,"record_revision",item.get("revision"),"fields",decisions));Service.audit(db,item,actor,"discovery.observed",map("source_id",id,"report_id",reportId,"fields",decisions));}
  db.update("INSERT INTO os_discovery_report(report_id,source_id,external_id,sha256,provenance_hash,observed_at,source_revision,created,actor_id,detail) VALUES(?,?,?,?,?,?,?,?,?,?)",reportId,id,external,digest,provenance,observed,source.get("revision"),now(),db.viewerId,JSON.writeValueAsString(map("outcomes",outcomes)));return receipt(db,reportId);
 }
 static void guard(Store.Db db,Map<String,Object> item)throws SQLException {if(!item.get("table").equals("cmdb_ci"))return;var identity=db.one("SELECT serial_number FROM os_discovery_identity WHERE record_id=?",item.get("sys_id"));if(identity!=null && !serial(object(item.get("data")).get("serial_number")).equals(identity.get("serial_number")))throw new Failure(409,"A discovered CI retains its canonical serial identity");String canonical=object(item.get("data")).getOrDefault("serial_number","").toString().strip().toUpperCase(Locale.ROOT);if(db.one("SELECT record_id FROM os_discovery_identity WHERE serial_number=? AND record_id<>?",canonical,item.get("sys_id"))!=null)throw new Failure(409,"This serial identity already belongs to a discovered CI");}
 static void deleting(Store.Db db,String id)throws SQLException {if(db.one("SELECT record_id FROM os_discovery_identity WHERE record_id=?",id)!=null)throw new Failure(409,"Retain identified CIs and their discovery evidence");}
}
